# Edition 2, items batch 3: rings, wands, staffs, rods, and armor.
# (name, category, rarity, attunement, text)
A = "Requires Attunement"
AS = "Requires Attunement by a Spellcaster"
ITEMS = [
# ================= RINGS =================
("Ring of the Kept Hour", "Ring", "Common", None, "While wearing this ring, you always know the time of day. You can set it to tighten gently at a time you choose, which wakes you without waking anyone else."),
("Ring of the Calm Pulse", "Ring", "Uncommon", A, "While wearing this ring, you have Advantage on saving throws to avoid or end the Frightened condition. Once per Long Rest, you can end the Frightened condition on yourself as a Bonus Action."),
("Ring of the Second Hand", "Ring", "Uncommon", A, "While wearing this ring, you can cast Mage Hand from it at will. The hand it creates can lift and carry up to 20 pounds."),
("Ring of the Wayfinder", "Ring", "Uncommon", None, "While wearing this ring, you can't become lost by nonmagical means, and you always know which way is north and the way back to the place where you last finished a Long Rest."),
("Ring of the Ember Ward", "Ring", "Rare", A, "While wearing this ring, you have Resistance to Fire damage. The ring has 3 charges and regains all expended charges daily at dawn. When a creature within 5 feet of you hits you with a melee attack, you can take a Reaction and expend 1 charge. The attacker makes a DC 15 Dexterity save, taking 3d6 Fire damage on a failed save or half as much on a successful one."),
("Ring of the Patient Spider", "Ring", "Rare", A, "While wearing this ring, you have a Climb Speed equal to your Speed, and you can move up, down, and across vertical surfaces and along ceilings while leaving your hands free. Once per dawn, you can cast Web (save DC 15) from the ring."),
("Ring of the Quiet Step", "Ring", "Rare", A, "While wearing this ring, you leave no tracks and make no sound when you walk. Once per dawn, you can cast Pass without Trace from it, and once per dawn, you can cast Invisibility from it, targeting only yourself."),
("Ring of the Bound Storm", "Ring", "Very Rare", A, "While wearing this ring, you have Resistance to Lightning and Thunder damage. The ring has 3 charges and regains 1d3 expended charges daily at dawn. You can expend 1 charge to cast Lightning Bolt (save DC 17) from it, or 3 charges to cast Chain Lightning (save DC 17) from it."),
("Ring of the Unshaken Mind", "Ring", "Very Rare", A, "While wearing this ring, you have Advantage on Wisdom and Charisma saving throws, and on Constitution saving throws that you make to maintain Concentration."),
("Ring of a Hundred Doors", "Ring", "Legendary", A, "This ring has 3 charges and regains all expended charges daily at dawn. While wearing it, you can expend 1 charge to cast Dimension Door from it, or all 3 charges to cast Teleport from it."),
# ================= WANDS =================
("Wand of Little Sparks", "Wand", "Common", None, "As a Bonus Action, you can point this wand at a candle, a torch, a pipe, a lamp, or a campfire within 30 feet and light it or snuff it out."),
("Wand of Sleet", "Wand", "Uncommon", None, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. As a Magic action, you can expend 1 charge to coat a 10-foot square within 60 feet with slick ice for 1 minute. The square is Difficult Terrain. Each creature in it when it appears, and each creature that enters it or ends its turn there, makes a DC 13 Dexterity save or has the Prone condition. If you expend the last charge, roll 1d20. On a 1, the wand melts."),
("Wand of the Stalwart Friend", "Wand", "Uncommon", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Shield of Faith from it, or 2 charges to cast Aid from it."),
("Wand of Hungry Shadows", "Wand", "Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Darkness from it, or 3 charges to cast Vampiric Touch from it (+7 to hit). Vampiric Touch cast from the wand doesn't require Concentration but lasts only 3 rounds."),
("Wand of the Thunderhead", "Wand", "Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Thunderwave (save DC 15) from it. For each additional charge you expend, the spell's level increases by 1, to a maximum of level 4. You can also expend 2 charges to cast Shatter (save DC 15) from it."),
("Wand of Withering", "Wand", "Very Rare", AS, "This wand of black bone has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Blight (save DC 17) from it, or 5 charges to cast Circle of Death (save DC 17) from it. Plants within 5 feet of the wand slowly wilt."),
("Wand of the Watchful Eye", "Wand", "Very Rare", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 2 charges to cast Arcane Eye from it, or 5 charges to cast Scrying (save DC 17) from it."),
("Wand of the Final Word", "Wand", "Legendary", AS, "This wand has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend 3 charges to cast Hold Monster (save DC 18) from it, or 5 charges to cast Power Word Stun from it."),
# ================= STAFFS =================
("Walking Staff of the Long Mile", "Staff", "Common", None, "This plain ash staff knows how far it has walked. On command, it tells you the distance you have walked with it since dawn. Leaning on it, you can stand still for up to 8 hours without tiring."),
("Staff of the Hearthkeeper", "Staff", "Uncommon", AS, "This staff can be wielded as a Quarterstaff. It has 4 charges and regains 1d4 expended charges daily at dawn. While holding it, you can expend 1 charge to cast Goodberry or Cure Wounds from it, or 2 charges to cast Protection from Poison from it."),
("Staff of the Lamplighter", "Staff", "Uncommon", AS, "This staff can be wielded as a Quarterstaff, and its tip sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet on command. It has 3 charges and regains all expended charges daily at dawn. You can expend 1 charge to cast Faerie Fire (save DC 13) from it, or 2 charges to cast Continual Flame from it."),
("Staff of the Barrow Warden", "Staff", "Rare", AS, "This staff can be wielded as a Quarterstaff. It has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend charges to cast one of the following spells from it (save DC 15): Protection from Evil and Good (1 charge), Speak with Dead (3 charges), or Spirit Guardians (3 charges)."),
("Staff of Mirrors", "Staff", "Rare", AS, "This staff of polished silver can be wielded as a Quarterstaff. It has 7 charges and regains 1d6 + 1 expended charges daily at dawn. While holding it, you can expend charges to cast one of the following spells from it (save DC 15): Blur (2 charges), Mirror Image (2 charges), or Major Image (3 charges)."),
("Staff of the Long Watch", "Staff", "Very Rare", AS, "This staff is a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. It has 10 charges and regains 1d6 + 4 expended charges daily at dawn. While holding it, you can expend charges to cast one of the following spells from it (save DC 17): Alarm (1 charge), Arcane Eye (4 charges), or Hold Monster (5 charges). While you hold the staff, you can't be surprised."),
("Staff of the Turning Seasons", "Staff", "Legendary", "Requires Attunement by a Druid", "This staff is a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it. While holding it, you gain a +3 bonus to spell attack rolls. It has 20 charges and regains 2d8 + 4 expended charges daily at dawn. You can expend charges to cast one of the following spells from it (save DC 18): Plant Growth (3 charges), Ice Storm (4 charges), Sunbeam (6 charges), or Control Weather (8 charges)."),
# ================= RODS =================
("Rod of the Herald", "Rod", "Uncommon", A, "While holding this rod, you can make your voice carry clearly up to 1 mile. The rod has 3 charges and regains all expended charges daily at dawn. You can expend 1 charge to cast Command (save DC 13) from it."),
("Rod of Measured Weight", "Rod", "Uncommon", None, "While holding this rod, you can take a Magic action to learn the exact weight of an object you can see within 30 feet. Once per dawn, you can touch an object that weighs up to 500 pounds and isn't worn or carried by another creature. For 10 minutes, it weighs only 1 pound."),
("Rod of the Warden's Chain", "Rod", "Rare", A, "This rod has 3 charges and regains all expended charges daily at dawn. As a Magic action, you can expend 1 charge to fling a chain of force at a Large or smaller creature you can see within 30 feet. The creature makes a DC 15 Strength save or has the Restrained condition for 1 minute. It repeats the save at the end of each of its turns, ending the effect on itself on a success."),
("Rod of Hushed Magic", "Rod", "Rare", A, "While holding this rod, you have Advantage on Intelligence (Arcana) checks to identify a spell or a magic effect. Once per dawn, you can cast Counterspell (save DC 15) from the rod."),
("Rod of the Unbent Line", "Rod", "Very Rare", A, "This rod is a perfectly straight bar of white metal. Once per dawn, you can cast Wall of Force from it. While the wall lasts, you have Advantage on saving throws to maintain Concentration on it."),
("Rod of the Second Sun", "Rod", "Very Rare", A, "On command, this golden rod sheds sunlight in a 30-foot radius and Dim Light for an additional 30 feet. Once per dawn, you can cast Sunbeam (save DC 17) from it."),
("Rod of the Sealed Gate", "Rod", "Legendary", A, "This rod has 3 charges and regains all expended charges daily at dawn. While holding it, you can expend 1 charge to cast Banishment (save DC 18) from it, or 3 charges to cast Plane Shift (save DC 18) from it. Once per dawn, as a Reaction when a creature you can see within 60 feet teleports, you can try to stop the teleport. The creature makes a DC 17 Charisma save. On a failed save, it stays where it is, and the action or the spell is wasted."),
# ================= ARMOR =================
("Jerkin of Many Colors", "Armor (Leather)", "Common", None, "As a Bonus Action, you can change the color and the pattern of this leather armor to any you have seen."),
("Rustless Mail", "Armor (Chain Mail)", "Common", None, "This chain mail never rusts and cleans itself of mud and blood overnight. You can don or doff it in half the normal time."),
("Hide of the Snow Bear", "Armor (Hide)", "Uncommon", None, "You have a +1 bonus to AC while wearing this armor. While you wear it, you don't suffer the effects of extreme cold, and you can sleep comfortably in snow."),
("Lantern Shield", "Armor (Shield)", "Uncommon", None, "On command, the boss of this shield sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. Once per dawn, as a Bonus Action, you can make it flash. Each creature of your choice within 15 feet of you makes a DC 13 Constitution save or has the Blinded condition until the end of its next turn."),
("Breastplate of the Quiet Heart", "Armor (Breastplate)", "Rare", A, "You have a +1 bonus to AC while wearing this armor, and you have Immunity to the Frightened condition."),
("Studded Leather of the Alley Cat", "Armor (Studded Leather)", "Rare", A, "You have a +1 bonus to AC while wearing this armor. While you wear it, you have a Climb Speed equal to your Speed, and when you fall 30 feet or less, you take no damage and land on your feet."),
("Half Plate of the Glacier", "Armor (Half Plate)", "Very Rare", A, "You have a +2 bonus to AC while wearing this armor, and you have Resistance to Cold damage. When a creature hits you with a melee attack, its Speed is reduced by 10 feet until the end of its next turn."),
("Shield of the Dawnless Wall", "Armor (Shield)", "Legendary", A, "While holding this shield, you have a +3 bonus to AC. This bonus is in addition to the shield's normal bonus to AC. Once per dawn, when you and allies within 10 feet of you must make a Dexterity save against an effect that deals damage in an area, you can take a Reaction to raise the shield. Each of you takes no damage on a successful save and only half damage on a failed one."),
]
